    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_1,'speak',17,NULL,NULL,'وارد کتابخانه شده‌ای و دنبال قفسهٔ کتاب‌های آلمانی می‌گردی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"وارد کتابخانه شده‌ای و دنبال قفسهٔ کتاب‌های آلمانی می‌گردی.","scenario_fa":"وارد کتابخانه شده‌ای و دنبال قفسهٔ کتاب‌های آلمانی می‌گردی.","accepted":["Wo ist das Regal mit Deutschbüchern?","Wo finde ich die deutschen Bücher?"],"acceptedIntents":["Wo ist das Regal mit Deutschbüchern?","Wo finde ich die deutschen Bücher?"],"accepted_intents":["Wo ist das Regal mit Deutschbüchern?","Wo finde ich die deutschen Bücher?"],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',11));
