    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'کتابدار تاریخ تحویل را نگفته؛ بپرس کتاب‌ها را تا چه زمانی می‌توانی نگه داری.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"کتابدار تاریخ تحویل را نگفته؛ بپرس کتاب‌ها را تا چه زمانی می‌توانی نگه داری.","scenario_fa":"کتابدار تاریخ تحویل را نگفته؛ بپرس کتاب‌ها را تا چه زمانی می‌توانی نگه داری.","accepted":["Bis wann darf ich die Bücher behalten?","Wann muss ich die Bücher zurückbringen?"],"acceptedIntents":["Bis wann darf ich die Bücher behalten?","Wann muss ich die Bücher zurückbringen?"],"accepted_intents":["Bis wann darf ich die Bücher behalten?","Wann muss ich die Bücher zurückbringen?"],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',11));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'موعد کتاب‌ها نزدیک است اما هنوز تمام نکرده‌ای؛ دربارهٔ تمدید مهلت بپرس.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"موعد کتاب‌ها نزدیک است اما هنوز تمام نکرده‌ای؛ دربارهٔ تمدید مهلت بپرس.","scenario_fa":"موعد کتاب‌ها نزدیک است اما هنوز تمام نکرده‌ای؛ دربارهٔ تمدید مهلت بپرس.","accepted":["Kann ich die Frist verlängern?","Wo kann ich die Ausleihe verlängern?"],"acceptedIntents":["Kann ich die Frist verlängern?","Wo kann ich die Ausleihe verlängern?"],"accepted_intents":["Kann ich die Frist verlängern?","Wo kann ich die Ausleihe verlängern?"],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',11));
  ELSEIF v_count=1 THEN
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>47 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0011' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=11;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_011()$$
DROP PROCEDURE IF EXISTS import_nova_series_011$$
